// POPRAWNIE: ExecutorService z watkiem daemon + limit czasu + fallback
ExecutorService executor = Executors.newSingleThreadExecutor(r -> {
    Thread t = new Thread(r);
    t.setDaemon(true);
    return t;
});
try {
    Future<Void> future = executor.submit(this::ivyResolve);
    future.get(10, TimeUnit.SECONDS);
} catch (TimeoutException e) {
    System.out.println("Rezolucja przekroczyla limit czasu - sprawdz polaczenie sieciowe");
}
